const bg = (k, extra = "") => `<g fill="none" stroke="${INK}" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"${extra}>${A[k]}</g>`;
const ico = (k, cls = "pg-ico") => `<svg class="${cls}" viewBox="0 0 100 104" aria-hidden="true">${bg(k)}</svg>`;
const put = (k, x, y, s, rot = 0) => `<g transform="translate(${x} ${y}) rotate(${rot} ${50 * s} ${52 * s}) scale(${s})">${bg(k)}</g>`;

// ---------- Données du potager (fictives mais plausibles) ----------
const MOIS = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"];
const MC = ["janv.", "févr.", "mars", "avr.", "mai", "juin", "juil.", "août", "sept.", "oct.", "nov.", "déc."];
// id, art, nom, latin, catégorie, semis/plantation, récolte, note
const VEG = [
  ["radis", "radish", "Radis rose", "Raphanus sativus", "racine", [3, 4, 5, 8, 9], [4, 5, 6, 9, 10, 11], "Prêt en quatre semaines : on le sème tous les quinze jours pour en avoir toujours de croquant."],
  ["pois", "pea", "Petit pois", "Pisum sativum", "fruit", [2, 3, 4], [5, 6, 7], "Écossé le jour même. Les premières gousses arrivent avec les premières chaleurs de mai."],
  ["epinard", "spinach", "Épinard", "Spinacia oleracea", "feuille", [3, 4, 9, 10], [4, 5, 10, 11, 12], "Deux saisons, au printemps et avant l'hiver : il craint la chaleur de l'été."],
  ["salade", "lettuce", "Laitue", "Lactuca sativa", "feuille", [2, 3, 4, 5, 6, 7, 8, 9], [4, 5, 6, 9, 10], "Semée en échelonné sous abri puis en plein champ pour ne jamais manquer de feuilles."],
  ["cerfeuil", "sprig", "Cerfeuil", "Anthriscus cerefolium", "aromate", [3, 4, 8, 9], [4, 5, 6, 9, 10], "L'herbe fine du printemps, anisée et délicate, à ajouter crue à la dernière minute."],
  ["tomate", "tomato", "Tomate", "Solanum lycopersicum", "fruit", [2, 3], [7, 8, 9, 10], "Une vingtaine de variétés anciennes, semées au chaud en février et plantées sous tunnel en mai."],
  ["courgette", "courgette", "Courgette", "Cucurbita pepo", "fruit", [4, 5], [6, 7, 8, 9], "Il faut la cueillir jeune, tous les deux jours : sinon elle dépasse la taille d'une batte."],
  ["aubergine", "aubergine", "Aubergine", "Solanum melongena", "fruit", [2, 3], [7, 8, 9], "Frileuse, elle ne quitte la serre qu'à la mi-mai et donne de belles peaux brillantes."],
  ["basilic", "basil", "Basilic", "Ocimum basilicum", "aromate", [4, 5], [6, 7, 8, 9], "On le pince régulièrement pour qu'il ramifie ; il n'aime ni le froid ni l'arrosage tardif."],
  ["carotte", "carrot", "Carotte", "Daucus carota", "racine", [3, 4, 5, 6], [6, 7, 8, 9, 10, 11, 12, 1], "Semée en terre fine et légère, elle se garde bien en silo de sable tout l'hiver."],
  ["betterave", "beet", "Betterave", "Beta vulgaris", "racine", [4, 5, 6], [7, 8, 9, 10, 11, 12], "Rouge, rose ou dorée : les feuilles se cuisinent comme des blettes, ne les jetez pas."],
  ["potimarron", "pumpkin", "Potimarron", "Cucurbita maxima", "fruit", [4, 5], [9, 10, 11, 12], "Récolté à pleine maturité, il se conserve jusqu'en février dans la grange sèche."],
  ["poireau", "leek", "Poireau", "Allium porrum", "bulbe", [2, 3, 4], [9, 10, 11, 12, 1, 2, 3], "Planté en juin dans une tranchée, il passe l'hiver au champ et supporte les gelées."],
  ["kale", "kale", "Chou kale", "Brassica oleracea", "feuille", [4, 5, 6], [10, 11, 12, 1, 2, 3], "Le gel le rend plus doux : ses feuilles frisées sont meilleures après les premières gelées."],
  ["ail", "garlic", "Ail", "Allium sativum", "bulbe", [10, 11], [6, 7], "Planté à l'automne, séché en tresses à l'ombre ; la tête en juillet, le goût toute l'année."],
  ["celeri", "celeriac", "Céleri-rave", "Apium graveolens var. rapaceum", "racine", [3, 4], [10, 11, 12, 1, 2], "Un légume d'hiver patient : cinq mois de culture pour une racine noueuse et parfumée."],
  ["fenouil", "fennel", "Fenouil", "Foeniculum vulgare", "bulbe", [6, 7], [9, 10, 11], "Semé à la mi-été pour éviter la montée en graines, récolté avant les gelées vives."],
  ["mache", "lettuce", "Mâche", "Valerianella locusta", "feuille", [8, 9], [11, 12, 1, 2, 3], "La salade de l'hiver, semée en août, cueillie à la main rosette par rosette."],
];
const VID = Object.fromEntries(VEG.map((v) => [v[0], v]));
const CATS = [["tous", "Tout"], ["feuille", "Feuilles"], ["racine", "Racines"], ["fruit", "Fruits"], ["bulbe", "Bulbes"], ["aromate", "Aromates"]];
const SEASONS = [
  { k: "printemps", n: "Printemps", pl: "I", art: "seedling", ids: ["radis", "pois", "epinard", "salade", "cerfeuil", "poireau"], from: "mars", note: "Les premiers semis sortent de terre" },
  { k: "ete", n: "Été", pl: "II", art: "tomato", ids: ["tomate", "courgette", "aubergine", "basilic", "carotte", "salade"], from: "juin", note: "Le soleil fait tout le travail" },
  { k: "automne", n: "Automne", pl: "III", art: "pumpkin", ids: ["potimarron", "betterave", "kale", "poireau", "fenouil", "celeri"], from: "septembre", note: "On ramasse, on range, on plante l'ail" },
  { k: "hiver", n: "Hiver", pl: "IV", art: "kale", ids: ["poireau", "celeri", "kale", "carotte", "mache", "betterave"], from: "décembre", note: "La terre se repose, les légumes-racines tiennent" },
];
// Poids relatifs d'un panier de saison (aromates : une botte)
const MIX = {
  printemps: [["radis", 6], ["epinard", 8], ["salade", 7], ["pois", 8], ["poireau", 10], ["cerfeuil", 0]],
  ete: [["tomate", 28], ["courgette", 18], ["aubergine", 10], ["carotte", 12], ["salade", 8], ["basilic", 0]],
  automne: [["potimarron", 22], ["betterave", 12], ["kale", 8], ["poireau", 14], ["fenouil", 10], ["celeri", 12]],
  hiver: [["poireau", 18], ["celeri", 16], ["kale", 12], ["carotte", 14], ["mache", 6], ["betterave", 10]],
};
const EXCL = [["choux", "Chou kale", ["kale"]], ["betterave", "Betterave", ["betterave"]], ["celeri", "Céleri-rave", ["celeri"]], ["aubergine", "Aubergine", ["aubergine"]], ["fenouil", "Fenouil", ["fenouil"]], ["courges", "Courges", ["potimarron", "courgette"]], ["tomate", "Tomate", ["tomate"]], ["aromates", "Aromates", ["basilic", "cerfeuil"]]];
const rangeText = (arr) => {
  const a = [...arr].sort((x, y) => x - y); if (!a.length) return "";
  if (a[0] === 1 && a[a.length - 1] === 12) { const gap = []; for (let m = 1; m <= 12; m++) if (!a.includes(m)) gap.push(m); if (gap.length) { const s = gap[gap.length - 1] + 1, e = gap[0] - 1; const w = []; for (let m = s; m <= 12; m++) w.push(m); for (let m = 1; m <= e; m++) w.push(m); return `${MOIS[w[0] - 1]} à ${MOIS[w[w.length - 1] - 1]}`; } }
  const out = []; let s = a[0], p = a[0];
  for (let i = 1; i <= a.length; i++) { if (a[i] === p + 1) { p = a[i]; continue; } out.push(s === p ? MOIS[s - 1] : `${MOIS[s - 1]} à ${MOIS[p - 1]}`); s = p = a[i]; }
  return out.join(" et ");
};

